def compute_diff(old_snapshot: Dict[str, str], new_snapshot: Dict[str, str]) -> Tuple[Set[str], Set[str], Set[str], Dict[str, str]]:
    """Compute the diff between two snapshots."""
    old_files = set(old_snapshot.keys())
    new_files = set(new_snapshot.keys())
    added = new_files - old_files
    removed = old_files - new_files
    common_files = old_files & new_files
    modified = {file: (old_snapshot[file], new_snapshot[file]) for file in common_files if old_snapshot[file] != new_snapshot[file]}
    renames = {}
    for old_file, new_file in zip(sorted(old_files), sorted(new_files)):
        if old_file == new_file:
            continue
        if hash_file(os.path.join(directory_path, old_file)) == hash_file(os.path.join(directory_path, new_file)):
